            if (n % 2 == 1) {
                int mid = n / 2;
                string s(n, '9');
                s[0] = s[n - 1] = '8';
                s[mid] = '8';
                return s;
            } else {
                int mid = (n - 2) / 2;
                string s(n, '9');
                s[0] = s[n - 1] = '8';
                s[mid] = s[mid + 1] = '7';
                return s;
            }
